<main class="erp-page"><nav class="erp-breadcrumb"><a href="/erp/units">Unidades</a><span aria-hidden="true">/</span><span><?= $this->e((string)$unit['code']) ?></span></nav><?php $this->insert('components/erp-page-header',['heading'=>'Unidade '.(string)$unit['code'],'description'=>(string)($unit['condominium_name']?:$unit['condominium_legal_name']).($unit['block_name']?' · '.$unit['block_name']:''),'kicker'=>'CADASTRO · ERP','actionHref'=>'/erp/units/'.(int)$unit['id'].'/edit','actionLabel'=>'Editar cadastro']); ?><section class="erp-panel erp-person-summary"><div><span>Condomínio</span><strong><?= $this->e((string)($unit['condominium_name']?:$unit['condominium_legal_name'])) ?></strong></div><div><span>Bloco / torre</span><strong><?= $this->e((string)($unit['block_name']?:'—')) ?></strong></div><div><span>Unidade</span><strong><?= $this->e((string)$unit['code']) ?></strong></div><div><span>Complemento / situação</span><strong><?= $this->e((string)($unit['complement']?:'—').' · '.($unit['status']==='active'?'Ativa':'Inativa')) ?></strong></div></section><section class="erp-panel erp-data-panel erp-detail-section"><header class="erp-panel-head"><div><h2>Pessoas relacionadas</h2><p><?= count($links) ?> vínculo(s), incluindo histórico encerrado</p></div></header><?php if($links===[]): ?><div class="erp-empty-state"><strong>Nenhum vínculo registrado</strong><p>Vínculos de proprietários e moradores podem ser adicionados no cadastro da pessoa.</p></div><?php else: ?><div class="erp-table-wrap"><table><thead><tr><th>Pessoa</th><th>Tipo</th><th>Condomínio</th><th>Fração ideal</th><th>Período</th><th>Situação</th></tr></thead><tbody><?php foreach($links as $link): ?><tr><td><a class="erp-record-link" href="/erp/people/<?= (int)$link['person_id'] ?>"><strong><?= $this->e((string)$link['full_name']) ?></strong><?php if($link['email']): ?><small><?= $this->e((string)$link['email']) ?></small><?php endif; ?></a></td><td><?= $this->e($roleLabels[$link['role']]??(string)$link['role']) ?></td><td><?= $this->e((string)($link['condominium_name']?:$link['condominium_legal_name'])) ?></td><td><?= $link['ownership_fraction_pct']===null?'—':$this->e(number_format((float)$link['ownership_fraction_pct'],4,',','.')).'%' ?></td><td><?= $this->e((string)$link['starts_at']) ?> → <?= $this->e((string)($link['ends_at']?:'Atual')) ?></td><td><span class="erp-status <?= (int)$link['is_current']===1?'ativo':'' ?>"><?= (int)$link['is_current']===1?'Ativo':'Histórico' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main>
